// The inputs a single quote is computed from. Today only `items` is consumed;
// `customer` is threaded through so policy-wide modifiers that depend on
// customer history (loyalty, follow-up contract) have a seat at the table.
type QuoteRequest = {
  customer: Customer;
  items: Item[];
};

type PolicyModifierRule = {
  applies: (request: QuoteRequest) => boolean;
  percent: number;
};

// Every test so far quotes a new customer's first contract, so this is the only
// policy-wide modifier the tests demand. Loyalty and follow-up land here later.
const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
];

const applyPolicyModifiers = (
  basePremium: number,
  request: QuoteRequest,
): number =>
  POLICY_MODIFIER_RULES.filter((rule) => rule.applies(request)).reduce(
    (premium, rule) => addPercent(premium, rule.percent),
    basePremium,
  );

